def group_dictionaries_by_key(dicts: list[dict], key: str) -> dict[str, list[dict]]:
    """Group a list of dictionaries by the value of a given key.

    Args:
        dicts: The list of dictionaries to group.
        key: The key to group by.

    Returns:
        A dictionary where keys are the values from the specified key and values are lists of dictionaries with that value.

    Example:
        >>> group_dictionaries_by_key([{'name': 'Alice', 'age': 30}, {'name': 'Bob', 'age': 25}], 'name')
        {'Alice': [{'name': 'Alice', 'age': 30}], 'Bob': [{'name': 'Bob', 'age': 25}]}
    """
    if not dicts:
        return {}
    grouped = {}
    for dictionary in dicts:
        if key not in dictionary:
            raise ValueError(f"Key '{key}' not found in one of the dictionaries.")
        value = dictionary[key]
        if value not in grouped:
            grouped[value] = []
        grouped[value].append(dictionary)
    return grouped
